import Header from '../components/Header';
import Footer from '../components/Footer';
import React from 'react';
import '../styles/Partitions.css';
import logo_partition from '../assets/logo_partition.png';
import { useState } from 'react';

const partitions = [
    {
        title: "Game of Thrones",
        file: "/documents/game_of_throne.pdf",
    },
    {
        title: "Divenire piano",
        file: "/documents/divenire_piano.pdf",
        image: "/images/divenire_piano.png"
    },
    {
        title: "Pirates des Caraïbes",
        file: "/documents/pirates.pdf",
        image: "/images/pirates.png"
    }
];

function Partitions() {
    const [showPreview, setShowPreview] = useState(false);

    return (
        <div>
            <Header />
            <main className="partitions-main">
                <h1>Partitions</h1>

                {/* GRILLE */}
                <div className="partitions-grid">
                    {partitions.map((partition, index) => (
                        <div
                            key={index}
                            className="partition-card"
                            onClick={() => setSelectedPdf(partition)}
                        >
                            <img src={partition.image} alt={partition.title} />
                            <p>{partition.title}</p>
                        </div>
                    ))}
                </div>

                {/* POPUP */}
                {selectedPdf && (
                    <div className="pdf-modal" onClick={() => setSelectedPdf(null)}>

                        <div
                            className="pdf-modal-content"
                            onClick={(e) => e.stopPropagation()}
                        >

                            <h2>{selectedPdf.title}</h2>

                            <iframe
                                src={selectedPdf.file}
                                title="PDF preview"
                            />

                            <a
                                href={selectedPdf.file}
                                target="_blank"
                                rel="noreferrer"
                                className="pdf-button"
                            >
                                Ouvrir en plein écran
                            </a>

                        </div>

                    </div>
                )}

            </main>
            <Footer />
        </div>
    );
}



export default Partitions;
